// Land mask for the homepage globe, derived from Natural Earth 50m land polygons
// (public domain, https://www.naturalearthdata.com/about/terms-of-use/).
// Source file: ne_50m_land.geojson from https://github.com/nvkelso/natural-earth-vector.
// Generated 2026-10-27 with an even-odd scanline rasterizer: 720x360 cells at 2 cells
// per degree, bit-packed MSB-first, base64-encoded. Cell (x, y) covers
// longitude [x / 2 - 180, (x + 1) / 2 - 180) and latitude [90 - (y + 1) / 2, 90 - y / 2).
// Regenerate: download the source GeoJSON and rasterize with the same cell layout;
// spot-check the sixteen homepage dish coordinates plus mid-ocean controls before replacing.
//
// BORDER_GRID_BASE64 (appended 2026-10-27): land-border cells on the same 720x360
// layout, derived from world.geo.json country polygons (Natural Earth-derived,
// public domain). A cell is set when it is land in the mask above and a
// 4-neighbor filled with a different country id. Coastlines are excluded.

export const LAND_GRID_WIDTH = 720;

export const LAND_GRID_HEIGHT = 180 * 2;

export const LAND_GRID_CELLS_PER_DEGREE = 2;

export const LAND_GRID_BASE64 =
  "";

export const BORDER_GRID_BASE64 =
  "";
